//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a temporary failure.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry, capped without overflowing while doubling.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let delay = self
            .base_delay_ms
            .checked_shl(retry_number)
            .unwrap_or(u64::MAX);
        delay.min(self.max_delay_ms)
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts = 0;

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < config.max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(attempts - 1));
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 15), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 15, 15]);
    }

    #[test]
    fn permanent_errors_are_returned_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let error = RetryError::Permanent("invalid input".into());

        assert_eq!(
            run_job(&config(4, 10, 100), &mut sleeper, || Err(error.clone())),
            Err(error)
        );
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_the_initial_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(1, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still unavailable".into()))
        });

        assert_eq!(
            result,
            Err(RetryError::Transient("still unavailable".into()))
        );
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn exhausted_transient_errors_are_returned_after_the_budget() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(3, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient(format!("failure {calls}")))
        });

        assert_eq!(result, Err(RetryError::Transient("failure 3".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn delay_calculation_saturates_before_shift_overflow() {
        let config = config(u32::MAX, u64::MAX, 123);
        assert_eq!(config.delay_for_retry(u32::MAX), 123);
    }
}

# jobrunner

Small job runner with a configurable, bounded retry policy.

## Retry policy

`RetryConfig` controls the retry budget and delays:

- `max_attempts` is the total number of job calls, including the initial call.
- `base_delay_ms` is the delay before the first retry.
- `max_delay_ms` caps every delay. Delays grow exponentially (`base`, `base * 2`, ...)
  and saturate at the cap without overflowing.

Only `RetryError::Transient` failures are retried. `RetryError::Permanent`
failures are returned immediately, without sleeping. When all attempts are
exhausted, the final error is returned.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = FakeSleeper::default();

let result = run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("service unavailable".into()))
});
assert!(result.is_err());
assert_eq!(sleeper.sleeps, vec![100, 200, 400]);
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_runner_retries_transient_failures_and_caps_delays() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 8,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls < 5 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![8, 16, 20, 20]);
}

#[test]
fn public_runner_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 8,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let error = RetryError::Permanent("invalid job".into());
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(error.clone())
    });

    assert_eq!(result, Err(error));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
